import { applySpecs, modelCurve, depreciation, escapeHTML, shortMake } from './logic.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',compare:'<path d="M4 4v16M10 8v12M16 3v17M22 11v9"/>',trend:'<path d="M3 6l6 6 5-3 7 10M15 19h6v-6"/>',database:'<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v14c0 4 16 4 16 0V5M4 12c0 4 16 4 16 0"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',plus:'<path d="M12 5v14M5 12h14"/>',bolt:'<path d="m13 2-9 12h7l-1 8 10-13h-8z"/>',gauge:'<path d="M4 18a9 9 0 1 1 16 0M12 12l5-5M7 18h10"/><circle cx="12" cy="12" r="1"/>',torque:'<path d="M5 19 19 5M14 4l6 0v6M4 14v6h6"/>',engine:'<path d="M6 8h10l3 3h3v6h-3l-3 3H6l-3-4V9h3zM9 4h6M12 4v4M1 12v5"/>',arrow:'<path d="M6 18 18 6M6 6h12v12"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 11h18"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.grid}</svg>`;
$$('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
const esc=escapeHTML;
const storage={get(k,f){try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}},set(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{}}};
let cars=[],catalog={},market={},selected=null;
const state={view:'explore',make:'BMW',category:'All cars',search:'',chart:'dyno',compare:storage.get('redline-compare',[]),picker:false,pending:null,scenarios:{},rate:12,price:80000,current:'',period:5,rpm:4000};
const colors=['#ff784a','#8cacf1','#a6cdb2'];
const fmt=n=>n==null?'—':Number(n).toLocaleString('en-US');
const money=n=>n==null?'—':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),3200)}
function setView(view){state.view=view;render();window.scrollTo({top:0,behavior:'instant'})}
function candidates(){const query=state.search.trim().toLowerCase();return cars.filter(c=>(!state.make||c.make===state.make)&&(state.category==='All cars'||c.category===state.category)&&(!query||(`${c.make} ${c.model} ${c.year}`.toLowerCase().includes(query)||`${c.make} ${c.model} ${c.year}`.toLowerCase().replace(/[^a-z0-9]/g,'').includes(query.replace(/[^a-z0-9]/g,'')))))}
function selectedFrom(list){return list.find(c=>c.year===2021&&c.model==='M3 Competition')||[...list].sort((a,b)=>Number(!!b.hp)-Number(!!a.hp)||b.year-a.year)[0]}
function selectCar(id){const c=cars.find(c=>c.id===id);if(!c)return;selected=c;state.rpm=4000;storage.set('redline-selected',id);render()}
function comparisonCars(){return [selected,...state.compare.map(id=>cars.find(c=>c.id===id))].filter((c,i,a)=>c&&a.findIndex(x=>x?.id===c.id)===i).slice(0,3)}
function addCompare(id){if(comparisonCars().some(c=>c.id===id)){toast('This car is already visible');return}if(comparisonCars().length>=3){toast('Remove a car before adding another.');return}state.compare=state.compare.filter(id=>id!==selected.id);state.compare.push(id);state.picker=false;storage.set('redline-compare',state.compare);render();toast('Car added alongside your dashboard')}
function openPicker(){state.pending=cars.find(c=>!comparisonCars().some(x=>x.id===c.id)&&c.hp)?.id;state.picker=true;render();$('#picker-model')?.focus()}
function title(){return {explore:'Explore cars',compare:'Compare cars',value:'Value & depreciation',sources:'Data sources'}[state.view]}
function pageHead(name,desc,action=''){return `<div class="page-head"><div><h1>${name}</h1><p>${desc}</p></div>${action||`<span class="date-pill">${icon('calendar')}2018 — 2024</span>`}</div>`}
function render(){
 $('#page-crumb').textContent=title();
 $$('.main-nav button').forEach(b=>{b.classList.toggle('active',b.dataset.view===state.view);b.setAttribute('aria-current',b.dataset.view===state.view?'page':'false')});
 const makeOrder=['BMW','Mercedes-Benz','Porsche','Lamborghini','Ferrari','McLaren Automotive','Bugatti'];
 $('#makes').innerHTML=makeOrder.map((m,i)=>`<button data-make="${m}" class="${state.make===m?'active':''}" aria-pressed="${state.make===m}"><span class="make-logo">${['B','M','P','L','F','Mc','EB'][i]}</span>${shortMake(m)}<span class="make-number">${new Set(cars.filter(c=>c.make===m).map(c=>c.family)).size}</span></button>`).join('');
 const list=candidates();if(state.view==='explore'&&(!selected||!list.includes(selected)))selected=selectedFrom(list);
 $('#app').innerHTML=`<div class="view-enter">${state.view==='explore'?explore(list):state.view==='value'?valueView():sourcesView()}</div>`;
 bind();
}
function selectors(list,selectedCar=selected,prefix=""){
 const selected=selectedCar;
 const fams=[...new Map(list.map(c=>[c.make+'|'+c.family,{make:c.make,family:c.family}])).values()];
 const familyCars=list.filter(c=>c.family===selected.family&&c.make===selected.make);
 const years=[...new Set(familyCars.map(c=>c.year))].sort((a,b)=>b-a);
 const trims=familyCars.filter(c=>c.year===selected.year).sort((a,b)=>a.model.localeCompare(b.model)||a.transmission.localeCompare(b.transmission));
 return `<div class="selectors"><div class="field"><label for="${prefix}model">Model</label><select id="${prefix}model">${fams.map(c=>`<option value="${esc(c.make+'|'+c.family)}" ${c.make===selected.make&&c.family===selected.family?'selected':''}>${esc(shortMake(c.make)+' '+c.family.replace(/^AMG /,''))}</option>`).join('')}</select></div><div class="field"><label for="${prefix}trim">Trim & transmission</label><select id="${prefix}trim">${trims.map(c=>`<option value="${c.id}" ${c.id===selected.id?'selected':''}>${esc(c.model)} · ${esc(c.transmission)}</option>`).join('')}</select></div><div class="field"><label for="${prefix}year">Model year</label><select id="${prefix}year">${years.map(y=>`<option ${y===selected.year?'selected':''}>${y}</option>`).join('')}</select></div></div>`;
}
function metric(label,value,unit,note,ico,accent=false){return `<div class="metric"><div class="metric-label">${icon(ico)}${label}</div><div class="metric-value ${accent?'orange':''}">${value}<small>${unit}</small></div><div class="metric-note">${note}</div></div>`}
function explore(list){
 const controls=`<div class="filter-row"><div class="category-tabs" role="group" aria-label="Car category">${['All cars','Sports cars','SUVs','Supercars','Hypercars'].map(c=>`<button data-category="${c}" class="${state.category===c?'active':''}" aria-pressed="${state.category===c}">${c}</button>`).join('')}</div><label class="search-box">${icon('search')}<input id="search" type="search" aria-label="Search cars" placeholder="Search models or years…" value="${esc(state.search)}"></label></div>`;
 const head=pageHead('Find your next obsession.','The numbers behind the cars worth knowing.');
 if(!selected)return head+controls+`<div class="empty"><h2>No cars match these filters.</h2><p>Try another manufacturer, model name or category.</p><button class="primary" id="reset-filters">Reset filters</button></div>`;
 const chosen=comparisonCars();
 const pending=cars.find(c=>c.id===state.pending);
 const picker=state.picker&&pending?`<section class="panel add-car-picker"><div class="panel-head"><div><h2>Add another car</h2><p>Choose any manufacturer, model, year and trim.</p></div><button class="secondary" id="cancel-add">Cancel</button></div>${selectors(cars,pending,'picker-')}<button class="primary" id="confirm-add">${icon('plus')}Compare this car</button></section>`:'';
 return head+controls+`<div class="comparison-toolbar"><p>${chosen.length>1?`${chosen.length} cars · full analytics side by side`:'Explore one car, or add another to compare.'}</p><button class="primary" id="add-another" ${chosen.length>=3?'disabled':''}>${icon('plus')}Add another car</button></div>`+picker+`<div class="car-dashboards ${chosen.length>1?'is-comparing':''}" style="--car-count:${chosen.length}">${chosen.map((c,i)=>`<article class="car-dashboard" data-car="${c.id}">${selectors(i===0?list:cars,c,'car-'+i+'-')}${carDashboard(c,i)}</article>`).join('')}</div>`;
}
function carDashboard(c,index){
 const hybrid=!!c.hybrid&&/hybrid/i.test(c.hybrid);
 const accel=c.zero60??c.zero100;
 const accelLabel=c.zero60!=null?'0–60 mph':c.zero100!=null?'0–100 km/h':'0–60 mph';
 return `<div class="car-header"><div><h2 class="car-name"><span class="car-make">${esc(shortMake(c.make))}</span> ${esc(c.family.replace(/^AMG /,''))}</h2><div class="car-subtitle"><span>${esc(c.model.replace(c.family,'').trim()||'Standard specification')}</span><span class="tag">${c.year}</span><span class="tag">${c.category}</span><span class="tag accent">${/Rear/.test(c.drive)?'RWD':/Front/.test(c.drive)?'FWD':'AWD'}</span></div></div>${index?`<button class="secondary" data-remove="${c.id}" aria-label="Remove ${esc(c.model)}">${icon('close')}Remove</button>`:''}</div>
 <div class="metrics">${metric(hybrid&&c.powerType!=='engine'?'System power':'Peak power',fmt(c.hp),'hp',c.hp?(c.referenceOnly?'Generation reference':'Manufacturer specification'):'Not verified for this trim','bolt',true)}${metric('Peak torque',fmt(c.torque),'lb-ft',c.torque?(c.referenceOnly?'Generation reference':'Manufacturer specification'):'Not verified for this trim','torque')}${metric(accelLabel,accel==null?'—':accel.toFixed(1),'sec',accel?'Manufacturer claim':'Not verified for this trim','gauge')}${metric('Engine',c.displacement?.toFixed(1)??'—','L',c.cylinders?`${c.cylinders} cylinders · ${hybrid?'hybrid':c.turbo?'turbocharged':'naturally aspirated'}`:'Manufacturer reference','engine')}</div>
 <div class="content-grid"><section class="panel"><div class="panel-head"><div><h2>Performance curves</h2><p>${state.chart==='dyno'?'Power delivery across the rev range':'An illustrative sprint to the published endpoint'}</p></div><div class="chart-tabs" role="group" aria-label="Performance graph"><button data-chart="dyno" class="${state.chart==='dyno'?'active':''}">Power & torque</button><button data-chart="accel" class="${state.chart==='accel'?'active':''}">Acceleration</button></div></div>${performanceChart(c)}</section>
 <section class="panel"><div class="panel-head"><div><h2>Under the hood</h2><p>${c.epa===false?'Manufacturer reference':'EPA vehicle specifications'}</p></div>${icon('engine')}</div><dl class="spec-list">${specRows([['Displacement',c.displacement?c.displacement.toFixed(1)+' L':'—'],['Cylinders',c.cylinders??'—'],['Induction',c.turbo?'Turbocharged':'Naturally aspirated'],['Transmission',c.transmission],['Drivetrain',c.drive],['Fuel',c.fuel],['Electrification',c.hybrid||'None recorded']])}</dl><a class="source-link" target="_blank" rel="noopener" href="${c.epa===false?c.source:'https://www.fueleconomy.gov/feg/Find.do?action=sbs&id='+c.id}">View ${c.epa===false?'manufacturer':'EPA'} record ${icon('arrow')}</a></section></div>
 <div class="bottom-grid"><section class="panel"><div class="panel-head"><div><h2>Fuel economy</h2><p>EPA estimates · miles per US gallon</p></div><button class="text-button" id="refresh-epa" ${c.epa===false?'disabled':''}>Refresh API</button></div><div class="mini-metrics"><div><strong id="city">${fmt(c.city)}</strong><span>City MPG</span></div><div><strong id="highway">${fmt(c.highway)}</strong><span>Highway MPG</span></div><div><strong id="combined">${fmt(c.combined)}</strong><span>Combined MPG</span></div></div><p class="chart-note" id="epa-status">${c.epa===false?'No matching EPA record in this snapshot.':`EPA snapshot · retrieved ${catalog.retrieved}. Refresh fetches this exact vehicle ID.`}</p></section>
 <section class="panel"><div class="panel-head"><div><h2>Market value</h2><p>US market · USD</p></div><span class="tag">${market[c.id]?'Listing snapshot':'Feed not connected'}</span></div>${market[c.id]?`<div class="value-result">${money(market[c.id].median)}</div><p class="info">Median asking price · ${market[c.id].sampleCount} listings · ${esc(market[c.id].asOf)}. Asking prices are not completed sale prices.</p>`:`<p class="info">A live valuation feed is needed for current prices. Explore how depreciation affects a price you enter.</p>`}<button class="source-link" data-view="value">Open depreciation calculator ${icon('arrow')}</button></section></div>
 <section class="panel inline-value"><h2>Depreciation scenario</h2><p class="info">Enter prices to calculate value loss. This is your scenario, not historical market data.</p><div class="value-inputs"><div class="field"><label for="purchase-${index}">Original price (USD)</label><input id="purchase-${index}" data-value="purchase" type="number" min="1" placeholder="e.g. 80000" value="${esc(state.scenarios[c.id]?.purchase||'')}"></div><div class="field"><label for="current-${index}">Current value (USD)</label><input id="current-${index}" data-value="current" type="number" min="0" placeholder="Enter your estimate" value="${esc(state.scenarios[c.id]?.current||'')}"></div><div class="field"><label for="years-${index}">Years owned</label><input id="years-${index}" data-value="years" type="number" min="1" max="50" value="${esc(state.scenarios[c.id]?.years||'5')}"></div></div><div data-value-result aria-live="polite"></div><div data-value-chart></div></section>
 ${c.specSource?`<div class="notes">Performance reference: <a href="${esc(c.specSource)}" target="_blank" rel="noopener">manufacturer specifications</a>. ${esc(c.specNote||'')} ${c.referenceOnly?'Generation reference; confirm the exact model-year build specification.':''}</div>`:`<div class="notes">EPA supplies engine and economy data, but not horsepower or acceleration. Unverified performance fields are left blank.</div>`}
 `.replace(/id="(rpm|rpm-output|refresh-epa|city|highway|combined|epa-status)"/g,(_,id)=>`data-part="${id}"`);
}
function specRows(rows){return rows.map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(String(v??'—'))}</dd></div>`).join('')}
function chartSVG(series,{maxX,maxY,xLabel,yLabel,xTicks=5,yTicks=4,accessLabel}){
 const w=state.view==='explore'&&comparisonCars().length>1?360:window.innerWidth<=680?Math.max(260,window.innerWidth-78):640,h=260,L=48,R=15,T=22,B=36,pw=w-L-R,ph=h-T-B;
 const x=v=>L+v/maxX*pw,y=v=>T+ph-v/maxY*ph;
 return `<div class="chart"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(accessLabel)}"><text x="${L}" y="12">${esc(yLabel)}</text>${Array.from({length:yTicks+1},(_,i)=>{let v=maxY*i/yTicks;return `<line class="gridline" x1="${L}" x2="${w-R}" y1="${y(v)}" y2="${y(v)}"/><text text-anchor="end" x="${L-10}" y="${y(v)+4}">${fmt(Math.round(v))}</text>`}).join('')}${Array.from({length:xTicks+1},(_,i)=>{let v=maxX*i/xTicks;return `<text text-anchor="middle" x="${x(v)}" y="${h-15}">${maxX>100?fmt(Math.round(v)):Number(v.toFixed(1))}</text>`}).join('')}${series.map(s=>`<path class="curve" stroke="${s.color}" d="${s.points.map((p,i)=>`${i?'L':'M'}${x(p[0]).toFixed(2)},${y(p[1]).toFixed(2)}`).join(' ')}"/>`).join('')}<text text-anchor="end" x="${w-R}" y="${h-1}">${esc(xLabel)}</text></svg></div>`;
}
function performanceChart(c){
 if(state.chart==='accel'){
 const t=c.zero60??c.zero100;const speed=c.zero60?60:100;const unit=c.zero60?'mph':'km/h';
 if(!t)return `<div class="empty-chart"><strong>No verified acceleration time</strong><p>We haven’t sourced an exact time for this configuration. Engine and economy data are available alongside.</p></div>`;
 const points=Array.from({length:31},(_,i)=>[t*i/30,speed*Math.pow(i/30,.78)]);
 return chartSVG([{points,color:colors[0]}],{maxX:Math.ceil(t),maxY:speed,xLabel:'TIME (SECONDS)',yLabel:unit.toUpperCase(),accessLabel:`Illustrative acceleration to ${speed} ${unit} in ${t} seconds`})+`<div class="legend"><span><i></i>0–${speed} ${unit} · ${t.toFixed(1)} s</span><span>Illustrative interpolation</span></div><p class="chart-note">Only the endpoint is a manufacturer claim. The line between start and finish is calculated, not measured acceleration telemetry.</p>`;
 }
 if(!c.hp||!c.torque||/hybrid/i.test(c.hybrid||''))return `<div class="empty-chart"><strong>${/hybrid/i.test(c.hybrid||'')?'Hybrid system output':'Power curve unavailable'}</strong><p>${/hybrid/i.test(c.hybrid||'')?'Engine and motor output occur at different speeds. Combined peak figures cannot produce a valid engine dyno curve.':'A sourced power and torque pair is needed to create the illustrative curve.'}</p></div>`;
 const curve=modelCurve(c.hp,c.torque);const maxY=Math.ceil(Math.max(c.hp,c.torque)/100)*100;
 return chartSVG([{points:curve.points.map(p=>[p.rpm,p.hp]),color:colors[0]},{points:curve.points.map(p=>[p.rpm,p.torque]),color:colors[1]}],{maxX:curve.maxRpm,maxY,xTicks:4,xLabel:'ENGINE SPEED (RPM)',yLabel:'HP / LB-FT',accessLabel:'Illustrative calculated horsepower and torque curves, not measured dyno results'})+`<div class="legend"><span><i></i>Power (hp)</span><span><i class="blue"></i>Torque (lb-ft)</span><span class="tag">Illustrative</span></div><div class="chart-readout"><span id="rpm-output">Move the slider to inspect the curve</span><input aria-label="Inspect engine RPM" type="range" id="rpm" min="1000" max="${curve.maxRpm}" step="100" value="4000"></div><p class="chart-note">Calculated from published peaks using hp = torque × RPM ÷ 5,252. Shape and RPM range are assumptions, not a measured dyno run or a factory rev limit.</p>`;
}
function peerTable(peers){return peers.length?`<div class="table-wrap"><table><thead><tr><th>MODEL / TRIM</th><th>YEAR</th><th>POWER</th><th>0–60 MPH</th><th>DRIVE</th><th><span class="sr-only">Compare</span></th></tr></thead><tbody>${peers.map(c=>`<tr><td><button class="row-button" data-select="${c.id}"><strong>${esc(shortMake(c.make)+' '+c.model.replace(/^AMG /,''))}</strong><small>${esc(c.transmission)}</small></button></td><td>${c.year}</td><td>${fmt(c.hp)}${c.hp?' hp':''}</td><td>${c.zero60?c.zero60.toFixed(1)+' s':'—'}</td><td>${/Rear/.test(c.drive)?'RWD':/Front/.test(c.drive)?'FWD':'AWD'}</td><td><button class="secondary" data-add="${c.id}" aria-label="Compare ${esc(c.model)}">${icon(state.compare.includes(c.id)?'check':'plus')}</button></td></tr>`).join('')}</tbody></table></div>`:''}
function valueView(){return pageHead('The other performance metric.','Understand value loss with your own price assumptions.')+`<div class="value-grid"><section class="panel"><h2>Depreciation scenario</h2><p class="info">A calculator, not a current market valuation. The starting $80,000 is an illustrative input.</p><div class="value-inputs" style="margin-top:22px"><div class="field wide"><label for="purchase">Original purchase price / MSRP (USD)</label><input id="purchase" type="number" min="1" max="100000000" step="100" value="${state.price}" inputmode="decimal"></div><div class="field wide"><label for="current-value">Known current value (USD, optional)</label><input id="current-value" type="number" min="0" max="100000000" step="100" value="${state.current}" placeholder="Enter a quote or appraisal" inputmode="decimal"></div><div class="wide"><div class="range-label"><label for="rate">Assumed annual depreciation</label><strong id="rate-label">${state.rate}%</strong></div><input id="rate" type="range" min="-15" max="30" step="1" value="${state.rate}"></div><div class="field wide"><label for="period">Years since purchase</label><select id="period">${Array.from({length:11},(_,i)=>i).map(i=>`<option value="${i}" ${i===state.period?'selected':''}>${i} ${i===1?'year':'years'}</option>`).join('')}</select></div></div><div class="callout">A negative depreciation rate models appreciation. Mileage, condition, options, accidents and collector demand are not included.</div></section><section class="panel"><div class="panel-head"><div><h2 id="value-heading">${state.current!==''?'Change from your entered values':'Modeled value after '+state.period+' years'}</h2><p id="value-kind">${state.current!==''?'User-provided valuation':'Illustrative scenario · USD'}</p></div><span class="tag accent">Calculated</span></div><div class="value-result orange" id="value-total"></div><p class="info" id="value-loss"></p><div id="value-chart"></div><p class="chart-note">Curve formula: starting price × (1 − annual rate)<sup>years</sup>. Entering a known current value switches to a straight line between your two values; intervening prices are not historical observations.</p></section></div><section class="panel" style="margin-top:24px"><h2>Current prices & actual price history</h2><p class="info">Live market data is not connected. MarketCheck requires an API key and an eligible plan. The included data refresh script can publish authenticated price snapshots to this static site without exposing the key. No synthetic history is presented as real sales data.</p><a class="source-link" href="https://docs.marketcheck.com/docs/api/cars/inventory/inventory-search" target="_blank" rel="noopener">MarketCheck data documentation ${icon('arrow')}</a></section>`}
function updateValue(){
 const p=Number(state.price),cv=state.current===''?null:Number(state.current);let result=depreciation(p,state.rate,state.period,cv);
 if(!result){$('#value-total').textContent='Enter a valid price';$('#value-loss').textContent='Original price must be greater than zero; current value cannot be negative.';$('#value-chart').innerHTML='';return}
 $('#value-heading').textContent=cv==null?`Modeled value after ${state.period} years`:'Change from your entered values';$('#value-kind').textContent=cv==null?'Illustrative scenario · USD':'User-provided valuation';$('#rate-label').textContent=state.rate+'%';$('#value-total').textContent=money(result.value);$('#value-loss').textContent=`${money(Math.abs(result.loss))} ${result.loss<0?'gained':'lost'} · ${Math.abs(result.percent).toFixed(1)}% ${result.loss<0?'appreciation':'depreciation'}`;
 const points=Array.from({length:state.period+1},(_,y)=>[y,cv==null?p*Math.pow(1-state.rate/100,y):p+(cv-p)*(state.period===0?1:y/state.period)]);
 $('#value-chart').innerHTML=chartSVG([{points,color:colors[0]}],{maxX:Math.max(state.period,1),maxY:Math.max(...points.map(p=>p[1]),1)*1.1,xTicks:Math.max(Math.min(state.period,5),1),xLabel:'YEARS SINCE PURCHASE',yLabel:'VALUE (USD)',accessLabel:'Calculated depreciation scenario, not observed historical prices'});
}
function sourcesView(){return pageHead('Good data. Clear boundaries.','Where the numbers come from, and what they can tell you.')+`<div class="source-grid"><section class="panel"><span class="status-tag">PUBLIC API · CONNECTED</span><h2>EPA / FuelEconomy.gov</h2><p>${cars.filter(c=>c.epa!==false).length} configurations, 2018–2024, imported from the official bulk vehicle dataset on ${catalog.retrieved}. Engine size, cylinder count, drive type, transmission, fuel and MPG remain tied to the original EPA ID.</p><p>The Refresh API button requests the exact record from the public REST API. If it fails, the dated local snapshot remains available.</p><a class="source-link" href="https://www.fueleconomy.gov/feg/ws/index.shtml" target="_blank" rel="noopener">API documentation ${icon('arrow')}</a></section><section class="panel"><span class="status-tag">CURATED REFERENCES</span><h2>Manufacturer performance figures</h2><p>Horsepower, torque and acceleration are overlaid only when a matching source is available. Each supported trim links to its manufacturer reference. Generation-level references are labeled where exact-year confirmation is absent.</p><p>Metric PS / CV converts to mechanical horsepower using 0.98632. Nm converts to lb-ft using 0.73756. 0–100 km/h is never relabeled as 0–60 mph.</p><p>Some EPA carlines combine multiple trims. Those records do not inherit a more specific trim’s performance.</p></section><section class="panel"><span class="status-tag warning">NOT CONNECTED</span><h2>MarketCheck valuations</h2><p>Current used prices require provider authentication and an eligible plan. An optional refresh script generates price snapshots for this static site. Credentials stay outside the public website.</p><p>Listing medians represent advertised asking prices, not completed transactions. Historical prices, original MSRP and depreciation are not inferred from those medians.</p><a class="source-link" href="https://docs.marketcheck.com/docs/api/cars" target="_blank" rel="noopener">Provider documentation ${icon('arrow')}</a></section><section class="panel"><span class="status-tag warning">CALCULATED · NOT MEASURED</span><h2>Dyno & depreciation curves</h2><p>Power curves demonstrate the mathematical relationship between horsepower, torque and RPM. Curve shape and operating range are assumptions. Hybrid system power cannot be plotted as an engine dyno and is excluded.</p><p>Depreciation uses the rate and values you supply. Acceleration curves interpolate to a sourced endpoint. Neither is recorded historical data or real telemetry.</p></section></div><div class="notes">Scope: selected performance models from BMW, Mercedes-AMG, Porsche, Lamborghini, Ferrari, McLaren and Bugatti. EPA reporting names determine available trims and years; this is not a complete worldwide production registry. US model-year availability can differ from global launch dates.</div>`}
function bind(){
 $$('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));
 $$('[data-make]').forEach(b=>b.onclick=()=>{state.make=b.dataset.make;state.category='All cars';state.search='';state.view='explore';selected=null;render()});
 $('#all-makes').onclick=()=>{state.make='';state.view='explore';render()};
 $$('[data-category]').forEach(b=>b.onclick=()=>{state.category=b.dataset.category;state.make='';selected=null;render()});
 const search=$('#search');if(search)search.oninput=e=>{const start=e.target.selectionStart;state.search=e.target.value;render();$('#search').focus();if(start!=null)$('#search').setSelectionRange(start,start)};
 $('#reset-filters')?.addEventListener('click',()=>{state.make='';state.category='All cars';state.search='';render()});
 $('#add-another')?.addEventListener('click',openPicker);
 $('#cancel-add')?.addEventListener('click',()=>{state.picker=false;render()});
 $('#confirm-add')?.addEventListener('click',()=>addCompare(state.pending));
 function bindSelectors(prefix,c,list,onChange){
 $('#'+prefix+'model')?.addEventListener('change',e=>{const [make,family]=e.target.value.split('|');const options=list.filter(x=>x.make===make&&x.family===family);onChange((options.find(x=>x.year===c.year&&x.hp)||selectedFrom(options)).id)});
 $('#'+prefix+'trim')?.addEventListener('change',e=>onChange(e.target.value));
 $('#'+prefix+'year')?.addEventListener('change',e=>{const options=list.filter(x=>x.make===c.make&&x.family===c.family&&x.year===Number(e.target.value));onChange((options.find(x=>x.model===c.model&&x.transmission===c.transmission)||options.find(x=>x.model===c.model)||selectedFrom(options)).id)});
 }
 if(state.picker){const pending=cars.find(c=>c.id===state.pending);if(pending)bindSelectors('picker-',pending,cars,id=>{state.pending=id;render()})}
 $$('.car-dashboard').forEach((root,i)=>{
 const c=cars.find(c=>c.id===root.dataset.car);
 bindSelectors('car-'+i+'-',c,i===0?candidates():cars,id=>{
 if(comparisonCars().some(x=>x.id===id&&x.id!==c.id)){toast('This configuration is already visible');render();return}
 if(i===0)selectCar(id);else{state.compare=state.compare.map(x=>x===c.id?id:x);storage.set('redline-compare',state.compare);render()}
 });
 const valueInputs=[...root.querySelectorAll('[data-value]')];
 const updateScenario=()=>{
 const values=Object.fromEntries(valueInputs.map(input=>[input.dataset.value,input.value]));state.scenarios[c.id]=values;
 const original=Number(values.purchase),current=Number(values.current),years=Number(values.years);
 const result=root.querySelector('[data-value-result]'),chart=root.querySelector('[data-value-chart]');
 if(!values.purchase||values.current===''||original<=0||current<0||years<1||years>50||![original,current,years].every(Number.isFinite)){result.textContent='Enter both prices and years owned to see the change.';chart.innerHTML='';return}
 const change=depreciation(original,0,years,current);if(!change){result.textContent='Enter prices up to $100,000,000.';chart.innerHTML='';return}
 result.textContent=`${money(Math.abs(change.loss))} ${change.loss<0?'gained':'lost'} · ${Math.abs(change.percent).toFixed(1)}%`;
 chart.innerHTML=chartSVG([{points:[[0,original],[years,current]],color:colors[0]}],{maxX:years,maxY:Math.max(original,current,1)*1.1,xTicks:Math.min(5,years),xLabel:'YEARS OWNED',yLabel:'USD',accessLabel:'Illustrative value change between your entered prices'})+'<p class="chart-note">Straight line between your two values; not recorded price history.</p>';
 };
 valueInputs.forEach(input=>input.oninput=updateScenario);updateScenario();
 root.querySelector('[data-part="rpm"]')?.addEventListener('input',e=>{const p=modelCurve(c.hp,c.torque).at(Number(e.target.value));root.querySelector('[data-part="rpm-output"]').textContent=`${fmt(p.rpm)} RPM · ${Math.round(p.hp)} hp · ${Math.round(p.torque)} lb-ft`});
 root.querySelector('[data-part="refresh-epa"]')?.addEventListener('click',()=>refreshEPA(c,root));
 });
 $$('[data-remove]').forEach(b=>b.onclick=()=>{state.compare=state.compare.filter(id=>id!==b.dataset.remove);storage.set('redline-compare',state.compare);render()});
 $$('[data-chart]').forEach(b=>b.onclick=()=>{state.chart=b.dataset.chart;render()});
 if(state.view==='value'){
 $('#purchase').oninput=e=>{state.price=e.target.value;updateValue()};$('#current-value').oninput=e=>{state.current=e.target.value;updateValue()};$('#rate').oninput=e=>{state.rate=Number(e.target.value);updateValue()};$('#period').onchange=e=>{state.period=Number(e.target.value);updateValue()};updateValue();
 }
}
async function refreshEPA(car,root){
 const part=name=>root.querySelector(`[data-part="${name}"]`);
 const id=car.id;const btn=part('refresh-epa');btn.disabled=true;btn.textContent='Refreshing…';
 try{const response=await fetch(`https://www.fueleconomy.gov/ws/rest/vehicle/${encodeURIComponent(id)}`,{headers:{Accept:'application/json'},signal:AbortSignal.timeout(10000)});if(!response.ok)throw new Error('API unavailable');const data=await response.json();if(String(data.id)!==id||![data.city08,data.highway08,data.comb08].every(x=>Number.isFinite(Number(x))))throw new Error('Invalid API response');const c=cars.find(x=>x.id===id);Object.assign(c,{city:Number(data.city08),highway:Number(data.highway08),combined:Number(data.comb08)});if(root.isConnected){part('city').textContent=c.city;part('highway').textContent=c.highway;part('combined').textContent=c.combined;part('epa-status').textContent=`Refreshed from EPA API · ${new Date().toLocaleString()}`;part('epa-status').classList.add('fuel-live')}toast('EPA figures refreshed')}
 catch{if(root.isConnected)part('epa-status').textContent=`Live EPA request unavailable. Showing the saved ${catalog.retrieved} snapshot. Try Refresh API again later.`;toast('Saved EPA data is still available')}
 finally{if(btn.isConnected){btn.disabled=false;btn.textContent='Refresh API'}}
}
async function start(){try{
 const responses=await Promise.all(['catalog','specs','market','supplemental'].map(n=>fetch(`data/${n}.json`).then(r=>{if(!r.ok)throw Error(n);return r.json()})));
 [catalog,,market]=responses;cars=[...catalog.vehicles,...responses[3]].map(c=>applySpecs(c,responses[1]));state.compare=state.compare.filter(id=>cars.some(c=>c.id===id)).slice(0,2);
 selected=cars.find(c=>c.id===storage.get('redline-selected',null));if(selected)state.make=selected.make;
 $('#loading').hidden=true;$('#app').hidden=false;render();
 }catch{$('#loading').innerHTML='<div class="empty"><h2>The catalogue could not load.</h2><p>Check your connection and reload to try again.</p><button class="primary" id="retry">Reload catalogue</button></div>';$('#retry').onclick=()=>location.reload()}}
matchMedia('(max-width: 680px)').addEventListener('change',()=>{if(cars.length)render()});
start();
